const developmentInfoDumpService = new DevelopmentInfoDumpService();

function isoToday() { const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`; }
function startOfWeek(date = new Date()) { const d = new Date(date); const day = d.getDay(); d.setHours(12,0,0,0); d.setDate(d.getDate() + (day === 0 ? -6 : 1 - day)); return d.toISOString().slice(0,10); }
function addDays(date: string, days: number) { const d = new Date(`${date}T12:00:00`); d.setDate(d.getDate()+days); return d.toISOString().slice(0,10); }
function formatDay(date: string, options: Intl.DateTimeFormatOptions = { weekday:'short', day:'numeric' }) { return new Date(`${date}T12:00:00`).toLocaleDateString(undefined, options); }
function studentName(studentId: string | null, students: Student[]) { if (!studentId) return 'Advisor'; return students.find((s)=>s.id===studentId)?.displayName ?? 'Student'; }
function dateLabel(task: Task) { const raw=task.dueDate??task.possibleDate; if(!raw) return 'No date'; const text=new Date(`${raw}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}); return task.dateConfidence==='possible'?`${text}?`:text; }
function confidenceLabel(value: DateConfidence) { return value==='confirmed'?'Confirmed':value==='possible'?'Possible date':'Undated'; }
function useShortViewport(maxHeight=700){const [short,setShort]=useState(()=>window.innerHeight<=maxHeight);useEffect(()=>{const onResize=()=>setShort(window.innerHeight<=maxHeight);window.addEventListener('resize',onResize);return()=>window.removeEventListener('resize',onResize)},[maxHeight]);return short;}
function calendarHourLabel(hour:number,format:AppSettings['calendarTimeFormat']){if(hour===24)return format==='24h'?'24:00':'12 AM next day';return formatCalendarClock(hour,0,format);}

function queueTaskChange(snapshot: AppSnapshot, task: Task, operation: 'upsert-task'|'delete-task') {
  if (!snapshot.settings.syncEnabled || !task.studentId) return { syncQueue:snapshot.syncQueue, nextSyncSequence:snapshot.nextSyncSequence };
  const student=snapshot.students.find((item)=>item.id===task.studentId);
  if(!student?.mailboxId) return { syncQueue:snapshot.syncQueue, nextSyncSequence:snapshot.nextSyncSequence };
  const envelope=createTaskEnvelope({mailboxId:student.mailboxId,studentId:task.studentId,deviceId:snapshot.deviceId,sequence:snapshot.nextSyncSequence,operation,task});
  return {syncQueue:[...snapshot.syncQueue,envelope],nextSyncSequence:snapshot.nextSyncSequence+1};
}

function queueTaskDifferences(before: AppSnapshot, after: AppSnapshot) {
  let queue=before.syncQueue; let sequence=before.nextSyncSequence;
  for(const task of after.tasks){
    const old=before.tasks.find((item)=>item.id===task.id);
    if(old && old.version===task.version && old.updatedAt===task.updatedAt) continue;
    const base={...after,syncQueue:queue,nextSyncSequence:sequence};
    const queued=queueTaskChange(base,task,task.deletedAt?'delete-task':'upsert-task'); queue=queued.syncQueue; sequence=queued.nextSyncSequence;
  }
  return {...after,syncQueue:queue,nextSyncSequence:sequence};
}

function newTaskFromSuggestion(item:InfoDumpItem,snapshot:AppSnapshot):Task{
  const now=new Date().toISOString(); const inferred=item.dueDate??item.possibleDate;
  return {id:crypto.randomUUID(),studentId:item.studentId,course:item.course,title:item.title,priority:item.priority,workStatus:'todo',dueDate:null,possibleDate:inferred,
    scheduledAt:item.time?`${inferred??isoToday()}T${item.time}:00`:null,durationMinutes:item.durationMinutes,recurringRule:null,source:'copilot',sourceRecordId:null,
    dateConfidence:inferred?'possible':'undated',notes:[item.notes,inferred?'Date originated from Info Dump and still needs human confirmation.':''].filter(Boolean).join('\n'),
    originDeviceId:snapshot.deviceId,createdByRole:snapshot.settings.role,createdAt:now,updatedAt:now,version:1,deletedAt:null};
}

export default function App(){
  const [snapshot,setSnapshot]=useState<AppSnapshot>(()=>import.meta.env.DEV?createDemoSnapshot():createInitialSnapshot());
  const [view,setView]=useState<AppView>('tasks'); const [booted,setBooted]=useState(false); const [notice,setNotice]=useState('');
  const [dump,setDump]=useState(''); const [organizing,setOrganizing]=useState(false); const [speaking,setSpeaking]=useState(false);
  const [suggestions,setSuggestions]=useState<InfoDumpItem[]>([]); const [selectedSuggestions,setSelectedSuggestions]=useState<Set<number>>(new Set());
  const [taskFilter,setTaskFilter]=useState<TaskFilter>('all'); const [undoTask,setUndoTask]=useState<Task|null>(null); const [taskClock,setTaskClock]=useState(Date.now());
  const [sectionOrder,setSectionOrder]=useState<SectionKey[]>(()=>{try{const saved=localStorage.getItem('torgy-section-order-v1');if(saved){const parsed=JSON.parse(saved) as SectionKey[];if(DEFAULT_SECTION_ORDER.every((key)=>parsed.includes(key)))return parsed}}catch{}return DEFAULT_SECTION_ORDER}); const [quickAdd,setQuickAdd]=useState<{scheduledAt:string}|null>(null);
  const [editingTask,setEditingTask]=useState<Task|null>(null); const [editingStudent,setEditingStudent]=useState<Student|'new'|null>(null);
  const [searchOpen,setSearchOpen]=useState(false); const [searchQuery,setSearchQuery]=useState('');
  const [calMode,setCalMode]=useState<'day'|'week'|'month'>('week'); const [calAnchor,setCalAnchor]=useState<string>(isoToday()); const [runtime,setRuntime]=useState<RuntimeInfo>({platform:'loading',storage:'loading',appDataDir:'',appMode:'development',supportsCoordinator:true,supportsStudent:true,supportsManagedAgent:false,supportsPortableSync:false,portableSyncConfigured:false,secureStorage:false,managedAgentInstalled:false,managedAgentConfigured:false});
  const [defaults,setDefaults]=useState<DeploymentDefaults>({copilotUrl:'',outlookTenantId:'',outlookClientId:'',syncSharePath:'',canvasBaseUrl:''});
  const [pairCode,setPairCode]=useState<{student:string;code:string;expiresAt:string}|null>(null); const [studentPairInput,setStudentPairInput]=useState('');
  const [canvasToken,setCanvasToken]=useState(''); const [canvasConnection,setCanvasConnection]=useState<{connected:boolean;accountLabel:string|null;baseUrl:string|null}>({connected:false,accountLabel:null,baseUrl:null});
  const [agent,setAgent]=useState<{installed:boolean;configured:boolean;running:boolean;pairedMailboxId:string|null;message:string}>({installed:false,configured:false,running:false,pairedMailboxId:null,message:''});
  const [readiness,setReadiness]=useState<ReadinessReport|null>(null);
  const fileInput=useRef<HTMLInputElement|null>(null); const backupInput=useRef<HTMLInputElement|null>(null); const dumpInput=useRef<HTMLTextAreaElement|null>(null); const saveTimer=useRef<number|null>(null); const snapshotRef=useRef(snapshot); const bgLock=useRef(false); const undoTimerRef=useRef<number|null>(null);
  snapshotRef.current=snapshot;

  const selectedStudentId=snapshot.settings.role==='student'?(snapshot.settings.selectedStudentId==='all'?snapshot.students[0]?.id??'all':snapshot.settings.selectedStudentId):snapshot.settings.selectedStudentId;
  const visibleTasks=useMemo(()=>snapshot.tasks.filter((t)=>!t.deletedAt&&(selectedStudentId==='all'||t.studentId===selectedStudentId)),[snapshot.tasks,selectedStudentId]);
  const sections=useMemo(()=>categorizeTasks(applyTaskFilter(visibleTasks,taskFilter,taskClock),taskClock),[visibleTasks,taskFilter,taskClock]);

  useEffect(()=>{let cancelled=false;(async()=>{try{const [stored,info,d]=await Promise.all([loadLocalSnapshot(),getRuntimeInfo(),getDeploymentDefaults()]);if(cancelled)return;setDefaults(d);let next=stored??createInitialSnapshot();if(!stored){next={...next,settings:{...next.settings,copilotUrl:d.copilotUrl,outlookTenantId:d.outlookTenantId,outlookClientId:d.outlookClientId,canvasBaseUrl:d.canvasBaseUrl}};}setSnapshot(next);setRuntime(info);setAgent(await managedAgentStatus());setCanvasConnection(await canvasStatus());}catch(e){if(!cancelled)setNotice(e instanceof Error?e.message:'Could not start Torgy.');}finally{if(!cancelled)setBooted(true)}})();return()=>{cancelled=true}},[]);
  useEffect(()=>{if(!booted)return;if(saveTimer.current)window.clearTimeout(saveTimer.current);saveTimer.current=window.setTimeout(()=>void saveLocalSnapshot({...snapshot,updatedAt:new Date().toISOString()}).catch((e)=>setNotice(e instanceof Error?e.message:'Local save failed.')),400);return()=>{if(saveTimer.current)window.clearTimeout(saveTimer.current)}},[snapshot,booted]);
  useEffect(()=>{localStorage.setItem('torgy-section-order-v1',JSON.stringify(sectionOrder))},[sectionOrder]);
  useEffect(()=>{const timer=window.setInterval(()=>setTaskClock(Date.now()),60_000);return()=>window.clearInterval(timer)},[]);
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(!(event.ctrlKey||event.metaKey))return;const key=event.key.toLowerCase();if(key==='k'){event.preventDefault();setSearchOpen(true);}if(key==='n'){event.preventDefault();setView('tasks');window.setTimeout(()=>dumpInput.current?.focus(),0);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
  useEffect(()=>{if(!booted)return;if(!dump.trim()){setSuggestions([]);setSelectedSuggestions(new Set());return;}const timer=window.setTimeout(()=>void organize(),450);return()=>window.clearTimeout(timer)},[dump,booted]);

  useEffect(()=>{if(!booted)return;const timer=window.setInterval(()=>{void(async()=>{if(bgLock.current)return;bgLock.current=true;try{let current=snapshotRef.current;const now=Date.now();if(current.settings.syncEnabled&&(!current.sync.lastAttemptAt||now-Date.parse(current.sync.lastAttemptAt)>=Math.max(10,current.settings.syncAutoSeconds)*1000)){current=(await runSyncCycle(current)).snapshot;}
      if(current.settings.outlookEnabled&&(!current.outlook.lastSyncAt||now-Date.parse(current.outlook.lastSyncAt)>=Math.max(30,current.settings.outlookAutoSyncSeconds)*1000)){const out=await runOutlookSync(current);current=queueTaskDifferences(current,out.snapshot);}if(current!==snapshotRef.current)setSnapshot(current);setAgent(await managedAgentStatus());}finally{bgLock.current=false}})()},10000);return()=>window.clearInterval(timer)},[booted]);

  function patchSettings(patch:Partial<AppSettings>){setSnapshot((p)=>({...p,settings:{...p.settings,...patch},updatedAt:new Date().toISOString()}));}
  function selectStudent(id:string){patchSettings({selectedStudentId:id});}
  function switchRole(next:Role){patchSettings({role:next,selectedStudentId:next==='student'?(snapshot.students[0]?.id??'all'):'all'});setView('tasks');}
  function moveSection(source:SectionKey,target:SectionKey){setSectionOrder((order)=>reorderSections(order,source,target));}
  function addCalendarTask(input:{title:string;studentId:string|null;scheduledAt:string;durationMinutes:number|null;priority:Priority;recurringRule?:string|null}){const task=buildQuickAddTask({...input,deviceId:snapshotRef.current.deviceId,createdByRole:snapshotRef.current.settings.role});setSnapshot((prev)=>{const next={...prev,tasks:[task,...prev.tasks]};const q=queueTaskChange(next,task,'upsert-task');return{...next,...q}});setQuickAdd(null);setNotice('Task added to Tasks and Calendar. Scheduled work only — no due date was set.');}
  function moveTaskSchedule(id:string,iso:string|null,occurrenceDay?:string){setSnapshot((prev)=>{const cur=prev.tasks.find((t)=>t.id===id);if(!cur)return prev;const changed=occurrenceDay&&iso&&cur.recurringRule?moveRecurringOccurrence(cur,occurrenceDay,iso):scheduleTaskAt(cur,iso);const q=queueTaskChange(prev,changed,'upsert-task');return{...prev,tasks:prev.tasks.map((t)=>t.id===id?changed:t),...q}})}

  async function runAllSync(){if(bgLock.current)return;bgLock.current=true;setNotice('Synchronizing…');try{let current=snapshotRef.current;if(current.settings.syncEnabled){const result=await runSyncCycle(current);current=result.snapshot;setNotice(result.message);}if(current.settings.outlookEnabled){const out=await runOutlookSync(current);current=queueTaskDifferences(current,out.snapshot);setNotice(out.message);}setSnapshot(current);setAgent(await managedAgentStatus());}finally{bgLock.current=false}}

  async function organize(){if(!dump.trim())return;setOrganizing(true);setNotice('');try{const service=snapshot.settings.copilotEnabled?new NativeCopilotInfoDumpService(snapshot.settings.copilotUrl):developmentInfoDumpService;const result=await service.organize(dump,{studentId:selectedStudentId==='all'?null:selectedStudentId,students:snapshot.students.map((student)=>({id:student.id,displayName:student.displayName}))});setSuggestions(result.items);setSelectedSuggestions(new Set(result.items.map((_,i)=>i)));if(result.provider==='development-fallback')setNotice('Development organizer only. Enable the approved AI organizer for full language cleanup.');}catch(e){setNotice(e instanceof Error?e.message:'Could not organize Info Dump.')}finally{setOrganizing(false)}}
  async function speak(){setSpeaking(true);setNotice('Listening locally…');try{const r=await dictateOnce();setDump((p)=>[p.trim(),r.text.trim()].filter(Boolean).join(' '));setNotice(r.text?`Local transcription captured with ${r.engine}.`:'No speech detected.');}catch(e){setNotice(e instanceof Error?e.message:'Speech capture failed.')}finally{setSpeaking(false)}}
  function addSuggestions(){const chosen=suggestions.filter((_,i)=>selectedSuggestions.has(i));const newTasks=chosen.map((x)=>newTaskFromSuggestion(x,snapshot));setSnapshot((prev)=>{let next={...prev,tasks:[...newTasks,...prev.tasks]};for(const t of newTasks){const q=queueTaskChange(next,t,'upsert-task');next={...next,...q};}return next});setSuggestions([]);setSelectedSuggestions(new Set());setDump('');setNotice(`${newTasks.length} item(s) added. Any AI-derived date remains Possible until a human confirms it.`)}
  function toggleDone(id:string){
    const cur=snapshotRef.current.tasks.find((t)=>t.id===id);
    if(!cur)return;
    const becomingDone=cur.workStatus!=='done';
    setSnapshot((prev)=>{const task=prev.tasks.find((t)=>t.id===id);if(!task)return prev;const now=new Date().toISOString();const changed={...task,workStatus:(task.workStatus==='done'?'todo':'done') as Task['workStatus'],completedAt:task.workStatus==='done'?null:now,version:task.version+1,updatedAt:now};const q=queueTaskChange(prev,changed,'upsert-task');return{...prev,tasks:prev.tasks.map((t)=>t.id===id?changed:t),...q}});
    if(becomingDone){if(undoTimerRef.current)window.clearTimeout(undoTimerRef.current);setUndoTask(cur);undoTimerRef.current=window.setTimeout(()=>setUndoTask(null),5000);}else{if(undoTimerRef.current)window.clearTimeout(undoTimerRef.current);setUndoTask(null);}
  }
  function saveTask(updated:Task){setSnapshot((prev)=>{const cur=prev.tasks.find((t)=>t.id===updated.id);if(!cur)return prev;const changed={...updated,version:cur.version+1,updatedAt:new Date().toISOString()};const q=queueTaskChange(prev,changed,'upsert-task');return{...prev,tasks:prev.tasks.map((t)=>t.id===changed.id?changed:t),...q}});setEditingTask(null)}
  function removeTask(id:string){setSnapshot((prev)=>{const cur=prev.tasks.find((t)=>t.id===id);if(!cur)return prev;const changed={...cur,deletedAt:new Date().toISOString(),version:cur.version+1,updatedAt:new Date().toISOString()};const q=queueTaskChange(prev,changed,'delete-task');return{...prev,tasks:prev.tasks.map((t)=>t.id===id?changed:t),...q}});setEditingTask(null)}
  function undoComplete(){if(!undoTask)return;const original=undoTask;if(undoTimerRef.current)window.clearTimeout(undoTimerRef.current);setUndoTask(null);setSnapshot((prev)=>{const current=prev.tasks.find((task)=>task.id===original.id);if(!current||current.workStatus!=='done')return prev;const changed={...current,workStatus:original.workStatus,completedAt:original.completedAt??null,version:current.version+1,updatedAt:new Date().toISOString()};const queued=queueTaskChange(prev,changed,'upsert-task');return{...prev,tasks:prev.tasks.map((task)=>task.id===original.id?changed:task),...queued}});}
  function patchSuggestion(index:number,patch:Partial<InfoDumpItem>){setSuggestions((prev)=>prev.map((item,i)=>i===index?{...item,...patch}:item));}
  function clearSuggestions(){setSuggestions([]);setSelectedSuggestions(new Set());setDump('');}
  function saveStudent(d:Pick<Student,'id'|'displayName'|'initials'|'mailboxId'|'canvasUserId'>){const name=d.displayName.trim();if(!name)return;setSnapshot((prev)=>{const existing=prev.students.find((s)=>s.id===d.id);const student:Student={id:d.id||crypto.randomUUID(),displayName:name,initials:d.initials.trim()||name.split(/\s+/).slice(0,2).map((p)=>p[0]?.toUpperCase()??'').join(''),canvasUserId:d.canvasUserId?.trim()||null,syncState:existing?.syncState??'offline',pairingState:existing?.pairingState??'unpaired',mailboxId:d.mailboxId||crypto.randomUUID(),peerPublicKey:existing?.peerPublicKey??null,lastSyncAt:existing?.lastSyncAt??null};return{...prev,students:existing?prev.students.map((s)=>s.id===student.id?student:s):[...prev.students,student]}});setEditingStudent(null)}
  function removeStudent(id:string){setSnapshot((p)=>({...p,students:p.students.filter((s)=>s.id!==id),settings:{...p.settings,selectedStudentId:p.settings.selectedStudentId===id?'all':p.settings.selectedStudentId}}));setEditingStudent(null)}
  async function downloadBackup(){const json=await exportBackupJson(snapshot);const blob=new Blob([json],{type:'application/json'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=`torgy-backup-${isoToday()}.json`;a.click();URL.revokeObjectURL(href);setNotice('Local JSON backup prepared. Store it only in an approved location.')}
  async function restoreBackup(file:File){try{const restored=await parseBackupFile(file);setSnapshot({...restored,updatedAt:new Date().toISOString()});setNotice(`Backup restored. ${restored.tasks.filter((task)=>!task.deletedAt).length} active task(s) and ${restored.students.length} student(s) loaded.`);}catch(e){setNotice(e instanceof Error?e.message:'Backup restore failed.')}finally{if(backupInput.current)backupInput.current.value=''}}
  async function checkReadiness(){setNotice('Checking Torgy readiness…');try{const report=await runReadinessCheck(snapshotRef.current,runtime);setReadiness(report);const blocked=report.checks.filter((item)=>item.status==='blocked').length;const warnings=report.checks.filter((item)=>item.status==='warning').length;setNotice(report.ready?`Readiness check complete: ${warnings} warning(s), no blockers.`:`Readiness check found ${blocked} blocker(s) and ${warnings} warning(s).`);}catch(e){setNotice(e instanceof Error?e.message:'Readiness check failed.')}}
  async function importFile(file:File){try{const records=await parseAcademicFile(file);const result=importAcademicRecords(snapshotRef.current,records);const next=queueTaskDifferences(snapshotRef.current,result.snapshot);setSnapshot(next);setNotice(`Imported ${result.inserted} new and ${result.updated} matching assignment(s). ${result.review?`${result.review} row(s) need student/date review.`:''}`);}catch(e){setNotice(e instanceof Error?e.message:'Import failed.')}finally{if(fileInput.current)fileInput.current.value=''}}
  async function doCanvasSync(){try{const result=await syncCanvasAssignments(snapshotRef.current);const next=queueTaskDifferences(snapshotRef.current,result.snapshot);setSnapshot(next);setNotice(`Canvas: ${result.fetched} fetched, ${result.inserted} new, ${result.updated} updated. Detected text dates remain Possible.`);}catch(e){setNotice(e instanceof Error?e.message:'Canvas sync failed.')}}
  async function makePairCode(student:Student){try{const r=await createCoordinatorPairingCode(snapshotRef.current,student);setPairCode({student:student.displayName,code:r.code,expiresAt:r.expiresAt});setSnapshot((p)=>({...p,students:p.students.map((s)=>s.id===student.id?{...s,pairingState:'invite-created'}:s)}));}catch(e){setNotice(e instanceof Error?e.message:'Could not create pairing code.')}}
  async function pairStudent(){try{await requestStudentPairing(studentPairInput,snapshot.deviceId);setSnapshot((p)=>({...p,students:p.students.map((s,i)=>i===0?{...s,pairingState:'pairing',syncState:'pending'}:s),settings:{...p.settings,syncEnabled:true,syncTransportMode:'managed-agent'}}));setStudentPairInput('');setNotice('Pairing request queued. The managed backend will complete it when it can reach the university sync drive.');}catch(e){setNotice(e instanceof Error?e.message:'Pairing failed.')}}

  if(!booted)return <main className="app-loading"><p>Starting Torgy…</p></main>;
  if(!snapshot.settings.firstRunComplete)return <SetupDialog snapshot={snapshot} defaults={defaults} onComplete={setSnapshot}/>;

  const statusLabel=snapshot.sync.state==='error'?'Sync issue':snapshot.syncQueue.length?`${snapshot.syncQueue.length} queued`:'Local-first';
  const showStatusPill=snapshot.sync.state==='error'||snapshot.syncQueue.length>0;
  return <div className="app-shell">
    <header className="app-header"><strong className="app-brand">Torgy</strong>{showStatusPill&&<span className="status-pill">{statusLabel}</span>}<select className="role-select" aria-label="Switch role" value={snapshot.settings.role} onChange={(e)=>switchRole(e.target.value as Role)}><option value="coordinator">Advisor view</option><option value="student">Student view</option></select></header>
    <div className="app-body">
      <SideNav view={view} setView={(next)=>{if(next==='tasks'&&snapshot.settings.role==='coordinator')selectStudent('all');setView(next)}} role={snapshot.settings.role}/>
      <section className="app-content">
        {view==='tasks'&&<TasksView snapshot={snapshot} selectedStudentId={selectedStudentId} dump={dump} setDump={setDump} speaking={speaking} speak={speak} notice={notice} suggestions={suggestions} selectedSuggestions={selectedSuggestions} setSelectedSuggestions={setSelectedSuggestions} addSuggestions={addSuggestions} clearSuggestions={clearSuggestions} patchSuggestion={patchSuggestion} sections={sections} sectionOrder={sectionOrder} moveSection={moveSection} taskFilter={taskFilter} setTaskFilter={setTaskFilter} onToggle={toggleDone} onEdit={setEditingTask} onDelete={removeTask} onResolveReview={(id,res)=>setSnapshot((p)=>queueTaskDifferences(p,resolveDuplicateReview(p,id,res)))} dumpRef={dumpInput}/>}
        {view==='calendar'&&<CalendarView tasks={visibleTasks} students={snapshot.students} settings={snapshot.settings} mode={calMode} setMode={setCalMode} anchor={calAnchor} setAnchor={setCalAnchor} onEdit={setEditingTask} onMove={moveTaskSchedule} onQuickAdd={(scheduledAt)=>setQuickAdd({scheduledAt})}/>}
        {view==='students'&&snapshot.settings.role==='coordinator'&&<StudentsView students={snapshot.students} tasks={snapshot.tasks} onAdd={()=>setEditingStudent('new')} onEdit={setEditingStudent} onOpen={(id)=>{selectStudent(id);setView('tasks')}}/>}
        {view==='settings'&&<SettingsView snapshot={snapshot} patchSettings={patchSettings} runtime={runtime} notice={notice} setNotice={setNotice} onExport={downloadBackup} onRestore={()=>backupInput.current?.click()} onReadiness={checkReadiness} readiness={readiness} onSync={runAllSync} onImport={()=>fileInput.current?.click()} onCanvasSync={doCanvasSync} canvasToken={canvasToken} setCanvasToken={setCanvasToken} canvasConnection={canvasConnection} setCanvasConnection={setCanvasConnection} agent={agent} setAgent={setAgent} replaceSnapshot={setSnapshot} studentPairInput={studentPairInput} setStudentPairInput={setStudentPairInput} onPairStudent={pairStudent}/>}
      </section>
    </div>
    {undoTask&&<output className="undo-toast">Task completed<button onClick={undoComplete}>Undo</button></output>}
    <input ref={fileInput} type="file" accept=".json,.csv,.tsv,.txt" hidden onChange={(e)=>{const f=e.target.files?.[0];if(f)void importFile(f)}}/>
    <input ref={backupInput} type="file" accept=".json" hidden onChange={(e)=>{const f=e.target.files?.[0];if(f)void restoreBackup(f)}}/>
    <BottomNav view={view} setView={setView} role={snapshot.settings.role}/>
    {searchOpen&&<SearchDialog snapshot={snapshot} query={searchQuery} setQuery={setSearchQuery} onClose={()=>{setSearchOpen(false);setSearchQuery('')}} onOpenTask={(task)=>{setEditingTask(task);setSearchOpen(false);setSearchQuery('')}} onOpenStudent={(id)=>{selectStudent(id);setView('tasks');setSearchOpen(false);setSearchQuery('')}}/>}
    {editingTask&&<TaskDialog task={editingTask} students={snapshot.students} roleLabel={snapshot.settings.role==='coordinator'?'Advisor view':'Student view'} onClose={()=>setEditingTask(null)} onSave={saveTask} onDelete={()=>removeTask(editingTask.id)}/>}
    {editingStudent&&<StudentDialog student={editingStudent==='new'?null:editingStudent} onClose={()=>setEditingStudent(null)} onSave={saveStudent} onDelete={editingStudent==='new'?undefined:()=>removeStudent(editingStudent.id)} onPair={editingStudent==='new'?undefined:()=>{makePairCode(editingStudent);setEditingStudent(null)}}/>}
    {quickAdd&&<QuickAddDialog scheduledAt={quickAdd.scheduledAt} students={snapshot.students} canPickOwner={snapshot.settings.role==='coordinator'} defaultStudentId={selectedStudentId==='all'?null:selectedStudentId} onClose={()=>setQuickAdd(null)} onCreate={addCalendarTask}/>}
    {pairCode&&<SimpleDialog title={`Pair ${pairCode.student}`} onClose={()=>setPairCode(null)}><p>Give this one-time code to the student. It expires at {new Date(pairCode.expiresAt).toLocaleTimeString()}.</p><div className="pair-code">{pairCode.code}</div><p className="muted-copy">The student's Windows account never receives access to the staff drive. The managed local agent transports encrypted packets using the university-managed computer identity.</p></SimpleDialog>}
  </div>;
}

function SetupDialog({snapshot,defaults,onComplete}:{snapshot:AppSnapshot;defaults:DeploymentDefaults;onComplete:(s:AppSnapshot)=>void}){
  const [role,setRole]=useState<AppSettings['role']>('coordinator');const [label,setLabel]=useState('');
  function finish(){const id=crypto.randomUUID();const student:Student={id,displayName:label.trim()||'Student',initials:(label.trim()||'Student').split(/\s+/).slice(0,2).map((p)=>p[0]?.toUpperCase()??'').join(''),canvasUserId:null,syncState:'offline',pairingState:'unpaired',mailboxId:null,peerPublicKey:null,lastSyncAt:null};const settings={...snapshot.settings,firstRunComplete:true,role,coordinatorLabel:role==='coordinator'?(label.trim()||'Advisor'):'Advisor',selectedStudentId:role==='student'?id:'all',copilotUrl:snapshot.settings.copilotUrl||defaults.copilotUrl,copilotEnabled:Boolean(snapshot.settings.copilotUrl||defaults.copilotUrl),outlookTenantId:snapshot.settings.outlookTenantId||defaults.outlookTenantId,outlookClientId:snapshot.settings.outlookClientId||defaults.outlookClientId,syncSharePath:role==='student'?'':(snapshot.settings.syncSharePath||defaults.syncSharePath),syncEnabled:role==='student'||Boolean(snapshot.settings.syncSharePath||defaults.syncSharePath),syncTransportMode:role==='student'?'managed-agent':(snapshot.settings.syncSharePath||defaults.syncSharePath)?'staff-drive':'disabled' as AppSettings['syncTransportMode'],canvasBaseUrl:snapshot.settings.canvasBaseUrl||defaults.canvasBaseUrl};onComplete({...snapshot,students:role==='student'?[student]:[],settings});}
  return <div className="dialog-backdrop"><section className="dialog setup-dialog"><header><div><h2>Set up Torgy</h2><p className="muted-copy">The app and database stay on this Windows computer. Integrations are optional and can be configured later.</p></div></header><label>Use this installation as<select value={role} onChange={(e)=>setRole(e.target.value as AppSettings['role'])}><option value="coordinator">Advisor</option><option value="student">Student</option></select></label><label>{role==='coordinator'?'Advisor label':'Student name'}<input value={label} onChange={(e)=>setLabel(e.target.value)} placeholder={role==='coordinator'?'Advisor':'Your name'}/></label><div className="security-box"><ShieldCheck/><div><strong>Local-first defaults</strong><small>No hosted Torgy server, no telemetry, no student data in GitHub. Copilot, Outlook, Canvas, and the university sync drive are isolated connectors.</small></div></div><footer><span/><span/><button className="primary" onClick={finish}>Finish setup</button></footer></section></div>;
}

const FILTER_LABELS: {key:TaskFilter;label:string}[]=[{key:'all',label:'All'},{key:'advisor',label:'Advisor'},{key:'canvas',label:'Canvas'},{key:'recurring',label:'Recurring'},{key:'overdue',label:'Overdue'},{key:'completed',label:'Completed'}];

function SideNav({view,setView,role}:{view:AppView;setView:(v:AppView)=>void;role:Role}){const items:{view:AppView;icon:ReactNode;label:string;visible:boolean}[]=[{view:'tasks',icon:<ClipboardList size={18}/>,label:'Tasks',visible:true},{view:'calendar',icon:<CalendarDays size={18}/>,label:'Calendar',visible:true},{view:'students',icon:<Users size={18}/>,label:'Students',visible:role==='coordinator'},{view:'settings',icon:<Settings size={18}/>,label:'Settings',visible:true}];return <nav className="side-nav" aria-label="Primary">{items.filter((i)=>i.visible).map((i)=><button key={i.view} className={view===i.view?'active':''} onClick={()=>setView(i.view)}>{i.icon}<span>{i.label}</span></button>)}</nav>}

function TasksView({snapshot,selectedStudentId,dump,setDump,speaking,speak,notice,suggestions,selectedSuggestions,setSelectedSuggestions,addSuggestions,clearSuggestions,patchSuggestion,sections,sectionOrder,moveSection,taskFilter,setTaskFilter,onToggle,onEdit,onDelete,onResolveReview,dumpRef}:{snapshot:AppSnapshot;selectedStudentId:string;dump:string;setDump:(s:string)=>void;speaking:boolean;speak:()=>void;notice:string;suggestions:InfoDumpItem[];selectedSuggestions:Set<number>;setSelectedSuggestions:(s:Set<number>)=>void;addSuggestions:()=>void;clearSuggestions:()=>void;patchSuggestion:(index:number,patch:Partial<InfoDumpItem>)=>void;sections:Record<SectionKey,Task[]>;sectionOrder:SectionKey[];moveSection:(source:SectionKey,target:SectionKey)=>void;taskFilter:TaskFilter;setTaskFilter:(f:TaskFilter)=>void;onToggle:(id:string)=>void;onEdit:(t:Task)=>void;onDelete:(id:string)=>void;onResolveReview:(id:string,res:'merge'|'keep-separate')=>void;dumpRef:RefObject<HTMLTextAreaElement|null>}){
  const canEditOwner=snapshot.settings.role==='coordinator'&&selectedStudentId==='all';
  const [dragging,setDragging]=useState<SectionKey|null>(null);
  const dateHeading=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());
  const visibleSections=sectionOrder.filter((key)=>sections[key].length>0);
  const completedTitle=taskFilter==='completed'?'COMPLETED':'COMPLETED \u00b7 LAST 12 HRS';
  return <div className="tasks-page"><section className="tasks-heading"><p className="date-heading">{dateHeading}</p><select aria-label="Filter tasks" className="filter-select" value={taskFilter} onChange={(e)=>setTaskFilter(e.target.value as TaskFilter)}>{FILTER_LABELS.map(({key,label})=><option key={key} value={key}>{label}</option>)}</select></section>
  <section className="info-card"><textarea ref={dumpRef} value={dump} onChange={(e)=>setDump(e.target.value)} rows={2} placeholder={'Info dump\nType or speak naturally. Dates, spelling, and importance are organized automatically.'} aria-label="Info dump"/><div className="info-actions"><button className="secondary" onClick={speak} disabled={speaking}><Mic size={17}/>{speaking?'Listening\u2026':'Speak'}</button><button className="secondary photo-placeholder" disabled title="Photo extraction is coming soon"><ImagePlus size={17}/>{'Photo import \u00b7 coming soon'}</button></div>{notice&&<p className="notice">{notice}</p>}</section>
  {suggestions.length>0&&<section className="suggestion-card"><div className="suggestion-heading"><div><strong>Review and approve · {selectedSuggestions.size} selected</strong><small>Review and edit before adding. AI-derived dates stay Possible until you confirm them.</small></div><div className="suggestion-controls"><button className="secondary compact" onClick={()=>setSelectedSuggestions(new Set(suggestions.map((_,i)=>i)))}>Select all</button><button className="secondary compact" onClick={()=>setSelectedSuggestions(new Set())}>Select none</button><button className="secondary compact" onClick={clearSuggestions}>Remove all</button></div></div><div className="suggestion-list">{suggestions.map((item,i)=><div className="suggestion-row" key={`${item.title}-${i}`}><input type="checkbox" checked={selectedSuggestions.has(i)} onChange={(e)=>{const n=new Set(selectedSuggestions);e.target.checked?n.add(i):n.delete(i);setSelectedSuggestions(n);}}/><div className="suggestion-fields"><input className="suggestion-title-input" value={item.title} onChange={(e)=>patchSuggestion(i,{title:e.target.value})} aria-label="Suggestion title"/><div className="suggestion-meta"><select value={item.priority} onChange={(e)=>patchSuggestion(i,{priority:e.target.value as Priority})} aria-label="Priority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select><select value={item.durationMinutes??''} onChange={(e)=>patchSuggestion(i,{durationMinutes:e.target.value?Number(e.target.value):null})} aria-label="Duration"><option value="">No duration</option>{[15,30,45,60,90,120,180,240,480].map((n)=><option value={n} key={n}>{n} min</option>)}</select>{canEditOwner&&<select value={item.studentId??''} onChange={(e)=>patchSuggestion(i,{studentId:e.target.value||null})} aria-label="Owner"><option value="">Advisor</option>{snapshot.students.map((student)=><option value={student.id} key={student.id}>{student.displayName}</option>)}</select>}<input type="date" value={item.possibleDate??item.dueDate??''} onChange={(e)=>patchSuggestion(i,{possibleDate:e.target.value||null,dueDate:null})} aria-label="Date (becomes Possible)"/><input type="time" value={item.time??''} onChange={(e)=>patchSuggestion(i,{time:e.target.value||null})} aria-label="Time"/></div><small>{item.course??'No course'}{item.uncertain?' · review':''}</small></div></div>)}</div><div className="suggestion-approve-actions"><button className="primary add-suggestions" onClick={addSuggestions} disabled={![...selectedSuggestions].some((i)=>suggestions[i]?.title.trim())}>Approve selected</button><button className="secondary" onClick={clearSuggestions}>Clear</button></div></section>}
  {snapshot.duplicateReviews.length>0&&<section className="review-box"><strong>{snapshot.duplicateReviews.length} possible duplicate{snapshot.duplicateReviews.length===1?'':'s'} need review</strong>{snapshot.duplicateReviews.slice(0,4).map((review)=>{const existing=snapshot.tasks.find((task)=>task.id===review.possibleDuplicateId);return <div className="review-row" key={review.id}><span><b>{review.incomingTask.title}</b><small> looks like {existing?.title??'an existing task'} · {Math.round(review.score*100)}% match</small></span><button className="secondary compact" onClick={()=>onResolveReview(review.id,'merge')}>Merge</button><button className="secondary compact" onClick={()=>onResolveReview(review.id,'keep-separate')}>Keep both</button></div>})}</section>}
  {visibleSections.length>0?<div className="task-board"><p className="drag-hint"><GripVertical size={14}/>Drag a section heading to place it where you want.</p><div className="task-sections">{visibleSections.map((key)=><TaskSection key={key} sectionKey={key} title={key==='completed'?completedTitle:SECTION_TITLES[key]} tasks={sections[key]} students={snapshot.students} showOwner={snapshot.settings.role==='coordinator'&&selectedStudentId==='all'} onToggle={onToggle} onEdit={onEdit} onDelete={onDelete} dragging={dragging===key} onDragStart={()=>setDragging(key)} onDragEnd={()=>setDragging(null)} onDrop={(source)=>{moveSection(source,key);setDragging(null)}}/>)}</div></div>:<div className="empty">Nothing here yet. Use the info dump above to add tasks.</div>}</div>;
}

function taskMeta(task:Task,students:Student[],showOwner=false){const parts:string[]=[];if(showOwner)parts.push(studentName(task.studentId,students));if(task.course)parts.push(task.course);if(!task.course&&!showOwner)parts.push(studentName(task.studentId,students));parts.push(task.source[0].toUpperCase()+task.source.slice(1));if(task.durationMinutes)parts.push(task.durationMinutes>=480?'All day':`${task.durationMinutes} min`);if(task.scheduledAt)parts.push(`Scheduled ${new Date(task.scheduledAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`);const repeat=recurrenceSummary(task.recurringRule,task.scheduledAt);if(repeat)parts.push(repeat);return parts;}
function taskSideDate(task:Task){if(task.workStatus==='done')return new Date(task.completedAt??task.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});return dateLabel(task);}
function upcomingDayLabel(day:string){return new Date(`${day}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});}
function TaskSection({sectionKey,title,tasks,students,showOwner,onToggle,onEdit,onDelete,dragging,onDragStart,onDragEnd,onDrop}:{sectionKey:SectionKey;title:string;tasks:Task[];students:Student[];showOwner:boolean;onToggle:(id:string)=>void;onEdit:(t:Task)=>void;onDelete:(id:string)=>void;dragging:boolean;onDragStart:()=>void;onDragEnd:()=>void;onDrop:(source:SectionKey)=>void}){
  const rank={high:3,normal:2,low:1};
  const ordered=[...tasks].sort((a,b)=>(a.dueDate??a.possibleDate??'9999').localeCompare(b.dueDate??b.possibleDate??'9999')||rank[b.priority]-rank[a.priority]);
  let previousDay='';
  return <section className={`task-section${dragging?' dragging':''}`} onDragOver={(e)=>{e.preventDefault();e.dataTransfer.dropEffect='move'}} onDrop={(e)=>{e.preventDefault();const source=e.dataTransfer.getData('text/section-key') as SectionKey;if(source)onDrop(source)}}><div className="section-title" draggable onDragStart={(e)=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/section-key',sectionKey);onDragStart()}} onDragEnd={onDragEnd} aria-label={`Drag ${title} section`}><span className="section-grip"><GripVertical size={14}/>{title}</span><span>{tasks.length}</span></div><div className="task-list">{ordered.map((task)=>{const showDay=sectionKey==='upcoming'&&!!task.dueDate&&task.dueDate!==previousDay;previousDay=task.dueDate??previousDay;return <div key={task.id}>{showDay&&<h3 className="task-date-subhead">{upcomingDayLabel(task.dueDate!)}</h3>}<div className={`task ${task.workStatus==='done'?'done':''}`}><button className="check" onClick={()=>onToggle(task.id)} aria-label={task.workStatus==='done'?`Reopen ${task.title}`:`Complete ${task.title}`}>{task.workStatus==='done'&&<Check size={16}/>}</button><button className="task-body" onClick={()=>onEdit(task)}><strong>{task.title}</strong><small className="task-meta">{taskMeta(task,students,showOwner).map((part,index)=><span key={`${part}-${index}`}>{part}</span>)}</small><span className={`mobile-date-label ${task.dateConfidence}`}>{dateLabel(task)}</span></button><span className={`priority ${task.priority}`}>{task.priority}</span><span className={`task-date ${task.dateConfidence}`} title={confidenceLabel(task.dateConfidence)}>{taskSideDate(task)}</span>{task.workStatus==='done'?<button className="more trash" onClick={()=>onDelete(task.id)} aria-label={`Delete ${task.title}`} title="Delete"><Trash2 size={17}/></button>:<button className="more" onClick={()=>onEdit(task)} aria-label={`Edit ${task.title}`}><MoreHorizontal size={18}/></button>}</div></div>})}</div></section>;
}

function CalendarView({tasks,students,settings,mode,setMode,anchor,setAnchor,onEdit,onMove,onQuickAdd}:{tasks:Task[];students:Student[];settings:AppSettings;mode:'day'|'week'|'month';setMode:(m:'day'|'week'|'month')=>void;anchor:string;setAnchor:(s:string)=>void;onEdit:(t:Task)=>void;onMove:(id:string,iso:string|null,occurrenceDay?:string)=>void;onQuickAdd:(scheduledAt:string)=>void}){
  const [placing,setPlacing]=useState<string|null>(null);
  useEffect(()=>{if(window.matchMedia('(max-width: 767px)').matches)setMode('day')},[]);
  const open=tasks.filter((task)=>task.workStatus!=='done');
  const unscheduled=open.filter((task)=>!task.scheduledAt);
  const {startHour,endHour,slotCount}=getCalendarWindow(settings);
  const timeFormat=settings.calendarTimeFormat;
  const weekDays=Array.from({length:7},(_,index)=>addDays(startOfWeek(new Date(`${anchor}T12:00:00`)),index));
  const monthFirst=`${anchor.slice(0,7)}-01`;const monthDays=Array.from({length:42},(_,index)=>addDays(startOfWeek(new Date(`${monthFirst}T12:00:00`)),index));
  const days=mode==='day'?[anchor]:weekDays;
  const rangeDays=mode==='month'?monthDays:days;
  const occurrences=rangeDays.length?open.flatMap((task)=>occurrencesBetween(task,rangeDays[0],rangeDays[rangeDays.length-1])):[];
  const onDay=(day:string)=>occurrences.filter((item)=>item.scheduledAt.slice(0,10)===day);
  const dueOn=(day:string)=>open.filter((task)=>task.dateConfidence==='confirmed'&&task.dueDate===day);
  const shift=(dir:number)=>{if(mode==='day')setAnchor(addDays(anchor,dir));else if(mode==='week')setAnchor(addDays(anchor,dir*7));else{const d=new Date(`${anchor}T12:00:00`);d.setMonth(d.getMonth()+dir);setAnchor(d.toISOString().slice(0,10));}};
  const defaultHour=Math.max(startHour,Math.min(9,endHour-1));
  const defaultTime=`${String(defaultHour).padStart(2,'0')}:00`;
  const move=(id:string,day:string,time:string,occurrenceDay?:string)=>{onMove(id,`${day}T${time}:00`,occurrenceDay);setPlacing(null)};
  const activate=(day:string,time=defaultTime)=>{if(placing){const task=tasks.find((item)=>item.id===placing);move(placing,day,task?.scheduledAt?.slice(11,16)??time);return}onQuickAdd(`${day}T${time}:00`)};
  const dragTask=(task:Task,occurrenceDay?:string)=>({draggable:true,onDragStart:(event:ReactDragEvent)=>{event.stopPropagation();event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/task-id',task.id);if(occurrenceDay)event.dataTransfer.setData('text/occurrence-day',occurrenceDay)}});
  const drop=(event:ReactDragEvent,day:string,time=defaultTime)=>{event.preventDefault();const id=event.dataTransfer.getData('text/task-id');if(id)move(id,day,time,event.dataTransfer.getData('text/occurrence-day')||undefined)};
  const coreRangeLabel=mode==='month'?new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(`${anchor}T12:00:00`)):mode==='day'?formatDay(anchor,{weekday:'long',month:'long',day:'numeric'}):`${formatDay(weekDays[0],{month:'short',day:'numeric'})} – ${formatDay(weekDays[6],{month:'short',day:'numeric'})}`;
  const rangeLabel=coreRangeLabel;
  return <div className="calendar"><section className="page-title cal-title"><div><h1>Calendar</h1><p>{rangeLabel}</p></div><div className="calendar-controls"><div className="cal-modes">{(['day','week','month'] as const).map((item)=><button key={item} className={mode===item?'active':''} onClick={()=>setMode(item)}>{item}</button>)}</div><button className="icon-button" aria-label={`Previous ${mode}`} onClick={()=>shift(-1)}><ChevronLeft/></button><button className="secondary" onClick={()=>setAnchor(isoToday())}>Today</button><button className="icon-button" aria-label={`Next ${mode}`} onClick={()=>shift(1)}><ChevronRight/></button></div></section><p className="drag-hint calendar-hint">{placing?'Choose a slot for the selected task, or press it again to cancel.':<><span className="desktop-calendar-hint">Click anywhere to add. Drag tasks to move them.</span><span className="mobile-calendar-hint">Tap a time to add. Tap a task to edit it.</span></>}</p><div className={unscheduled.length?'cal-layout':'cal-layout solo'}>{unscheduled.length>0&&<aside className="cal-rail"><div className="section-title plain"><span>Unscheduled</span><span>{unscheduled.length}</span></div><div className="cal-rail-list">{unscheduled.map((task)=><button key={task.id} {...dragTask(task)} onClick={()=>setPlacing(placing===task.id?null:task.id)} className={placing===task.id?'placing':''}><span className="cal-grip"><GripVertical size={13}/></span><span className="cal-rail-copy"><strong>{task.title}</strong><small>{studentName(task.studentId,students)} · {dateLabel(task)}</small></span></button>)}</div></aside>}{mode==='month'?<MonthCalendar days={monthDays} anchorMonth={anchor.slice(0,7)} occurrences={occurrences} dueOn={dueOn} activate={activate} onEdit={onEdit} dragTask={dragTask} drop={drop} timeFormat={timeFormat}/>:<>{mode==='day'?<MobileDayAgenda day={anchor} occurrences={onDay(anchor)} due={dueOn(anchor)} activate={activate} onEdit={onEdit} students={students} startHour={startHour} endHour={endHour} timeFormat={timeFormat}/>:<MobileAgenda days={days} occurrences={occurrences} dueOn={dueOn} activate={activate} onEdit={onEdit} students={students} timeFormat={timeFormat}/>}<TimeGrid days={days} occurrences={occurrences} dueOn={dueOn} activate={activate} onEdit={onEdit} dragTask={dragTask} drop={drop} students={students} startHour={startHour} endHour={endHour} slotCount={slotCount} timeFormat={timeFormat}/></>}</div></div>;
}

const GRID_SLOT_HEIGHT=26;
const GRID_MOBILE_SLOT_HEIGHT=56;
function MobileDayAgenda({day,occurrences,due,activate,onEdit,students,startHour,endHour,timeFormat}:{day:string;occurrences:CalendarOccurrence[];due:Task[];activate:(day:string,time?:string)=>void;onEdit:(task:Task)=>void;students:Student[];startHour:number;endHour:number;timeFormat:AppSettings['calendarTimeFormat']}){
  const labels=Array.from({length:(endHour-startHour)*2},(_,index)=>{const minutes=startHour*60+index*30;return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`});
  const allDay=occurrences.filter((item)=>(item.task.durationMinutes??0)>=480);
  const timed=occurrences.filter((item)=>(item.task.durationMinutes??0)<480);
  return <section className="mobile-day-agenda">{(due.length>0||allDay.length>0)&&<div className="mobile-day-facts">{due.map((task)=><button key={`due-${task.id}`} onClick={()=>onEdit(task)}><span>Due</span><strong>{task.title}</strong><small>Confirmed academic due date</small></button>)}{allDay.map((item)=><button key={`${item.task.id}-${item.occurrenceDay}`} onClick={()=>onEdit(item.task)}><span>All day</span><strong>{item.task.title}</strong><small>{studentName(item.task.studentId,students)}</small></button>)}</div>}<div className="mobile-day-slots">{labels.map((label)=><div className="mobile-day-row" key={label}><span>{formatCalendarClock(Number(label.slice(0,2)),Number(label.slice(3,5)),timeFormat)}</span><button onClick={()=>activate(day,label)}>Tap to add</button></div>)}{timed.map((item)=>{const date=new Date(item.scheduledAt);const minutes=date.getHours()*60+date.getMinutes()-startHour*60;if(minutes<0||minutes>=labels.length*30)return null;const top=minutes/30*GRID_MOBILE_SLOT_HEIGHT+6;const height=Math.max(40,Math.min((item.task.durationMinutes??30)/30*GRID_MOBILE_SLOT_HEIGHT-12,labels.length*GRID_MOBILE_SLOT_HEIGHT-top));return <button key={`${item.task.id}-${item.occurrenceDay}`} className="mobile-day-event" style={{top,height}} onClick={()=>onEdit(item.task)}><strong>{item.task.title}</strong><span>{formatScheduledTime(item.scheduledAt,timeFormat)}{item.task.durationMinutes?`–${formatScheduledTime(new Date(date.getTime()+item.task.durationMinutes*60000).toISOString(),timeFormat)}`:''} · {studentName(item.task.studentId,students)}</span></button>})}</div></section>;
}

function MobileAgenda({days,occurrences,dueOn,activate,onEdit,students,timeFormat}:{days:string[];occurrences:CalendarOccurrence[];dueOn:(day:string)=>Task[];activate:(day:string,time?:string)=>void;onEdit:(task:Task)=>void;students:Student[];timeFormat:AppSettings['calendarTimeFormat']}){return <div className="mobile-agenda">{days.map((day)=>{const due=dueOn(day);const scheduled=occurrences.filter((item)=>item.scheduledAt.slice(0,10)===day);return <section key={day}><button className="mobile-agenda-head" onClick={()=>activate(day)}><strong>{formatDay(day,{weekday:'long'})}</strong><span>{formatDay(day,{month:'short',day:'numeric'})}</span><small>+ Add</small></button>{due.map((task)=><button key={`due-${task.id}`} onClick={()=>onEdit(task)} className="mobile-agenda-item"><span>Due</span><strong>{task.title}</strong><small>Confirmed due date</small></button>)}{scheduled.map((item)=><button key={`${item.task.id}-${item.occurrenceDay}`} onClick={()=>onEdit(item.task)} className="mobile-agenda-item"><span>{(item.task.durationMinutes??0)>=480?'All day':formatScheduledTime(item.scheduledAt,timeFormat)}</span><strong>{item.task.title}</strong><small>{studentName(item.task.studentId,students)}{item.moved?' · moved occurrence':''}</small></button>)}{!due.length&&!scheduled.length&&<button className="mobile-agenda-empty" onClick={()=>activate(day)}>Nothing scheduled · tap to add</button>}</section>})}</div>}

function MonthCalendar({days,anchorMonth,occurrences,dueOn,activate,onEdit,dragTask,drop,timeFormat}:{days:string[];anchorMonth:string;occurrences:CalendarOccurrence[];dueOn:(day:string)=>Task[];activate:(day:string,time?:string)=>void;onEdit:(task:Task)=>void;dragTask:(task:Task,occurrenceDay?:string)=>Record<string,unknown>;drop:(event:ReactDragEvent,day:string,time?:string)=>void;timeFormat:AppSettings['calendarTimeFormat']}){return <section className="cal-month"><div className="cal-month-head">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((day)=><span key={day}>{day}</span>)}</div><div className="cal-month-grid">{days.map((day)=>{const scheduled=occurrences.filter((item)=>item.scheduledAt.slice(0,10)===day);const facts=dueOn(day);const items=[...facts.map((task)=>({task,label:'Due',occurrenceDay:undefined as string|undefined})),...scheduled.map((item)=>({task:item.task,label:formatScheduledTime(item.scheduledAt,timeFormat),occurrenceDay:item.occurrenceDay}))];return <div key={day} onDragOver={(event)=>event.preventDefault()} onDrop={(event)=>drop(event,day)} onClick={()=>activate(day)} className={`cal-month-cell${day.slice(0,7)!==anchorMonth?' dim':''}${day===isoToday()?' today':''}`}><span className="cal-month-date">{Number(day.slice(8,10))}</span>{items.slice(0,3).map((item,index)=><button key={`${item.task.id}-${item.occurrenceDay??'due'}-${index}`} {...dragTask(item.task,item.occurrenceDay)} onClick={(event)=>{event.stopPropagation();onEdit(item.task)}} className="cal-chip">{item.label} {item.task.title}</button>)}{items.length>3&&<span className="cal-more">+{items.length-3} more</span>}</div>})}</div></section>}

function TimeGrid({days,occurrences,dueOn,activate,onEdit,dragTask,drop,students,startHour,endHour,slotCount,timeFormat}:{days:string[];occurrences:CalendarOccurrence[];dueOn:(day:string)=>Task[];activate:(day:string,time?:string)=>void;onEdit:(task:Task)=>void;dragTask:(task:Task,occurrenceDay?:string)=>Record<string,unknown>;drop:(event:ReactDragEvent,day:string,time?:string)=>void;students:Student[];startHour:number;endHour:number;slotCount:number;timeFormat:AppSettings['calendarTimeFormat']}){
  const scrollRef=useRef<HTMLDivElement|null>(null);
  const labels=Array.from({length:slotCount},(_,index)=>{const minutes=startHour*60+index*30;return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`});
  const labelEvery=slotCount>36?2:1;
  const totalHeight=slotCount*GRID_SLOT_HEIGHT;
  const columns=`repeat(${days.length},minmax(${days.length===1?'240px':'112px'},1fr))`;
  useEffect(()=>{if(!scrollRef.current)return;const preferred=Math.max(0,(8-startHour)*2*GRID_SLOT_HEIGHT);scrollRef.current.scrollTop=preferred},[startHour,slotCount,days.join('|')]);
  return <section className="time-calendar"><div className="time-head"><span/><div className="time-days" style={{gridTemplateColumns:columns}}>{days.map((day)=><button key={day} onClick={()=>activate(day)} className={day===isoToday()?'today':''}><small>{formatDay(day,{weekday:'short'}).toUpperCase()}</small><strong>{Number(day.slice(8,10))}</strong></button>)}</div></div><div className="all-day-row"><span>ALL-DAY</span><div className="all-day-days" style={{gridTemplateColumns:columns}}>{days.map((day)=><div key={day} onDragOver={(event)=>event.preventDefault()} onDrop={(event)=>drop(event,day)}>{dueOn(day).map((task)=><button key={`due-${task.id}`} onClick={()=>onEdit(task)} className="all-day-chip"><strong>{task.title}</strong><small>Confirmed academic due date</small></button>)}{occurrences.filter((item)=>item.scheduledAt.slice(0,10)===day&&(item.task.durationMinutes??0)>=480).map((item)=><button key={`${item.task.id}-${item.occurrenceDay}`} {...dragTask(item.task,item.occurrenceDay)} onClick={()=>onEdit(item.task)} className="all-day-chip scheduled"><strong>{item.task.title}</strong><small>{studentName(item.task.studentId,students)}</small></button>)}</div>)}</div></div><div className="time-scroll" ref={scrollRef}><div className="time-labels" style={{gridTemplateRows:`repeat(${slotCount},${GRID_SLOT_HEIGHT}px)`,height:totalHeight}}>{labels.map((label,index)=><span key={label}>{index%labelEvery===0?formatCalendarClock(Number(label.slice(0,2)),Number(label.slice(3,5)),timeFormat):''}</span>)}</div><div className="time-columns" style={{gridTemplateColumns:columns}}>{days.map((day)=><div key={day} className="time-day-column" style={{height:totalHeight,backgroundSize:`100% ${GRID_SLOT_HEIGHT}px`}} onClick={(event)=>{if(event.target!==event.currentTarget)return;const rect=event.currentTarget.getBoundingClientRect();const slot=Math.max(0,Math.min(slotCount-1,Math.floor((event.clientY-rect.top)/GRID_SLOT_HEIGHT)));activate(day,labels[slot])}} onDragOver={(event)=>{event.preventDefault();event.dataTransfer.dropEffect='move'}} onDrop={(event)=>{event.preventDefault();const rect=event.currentTarget.getBoundingClientRect();const slot=Math.max(0,Math.min(slotCount-1,Math.floor((event.clientY-rect.top)/GRID_SLOT_HEIGHT)));drop(event,day,labels[slot])}}>{occurrences.filter((item)=>{if(item.scheduledAt.slice(0,10)!==day||(item.task.durationMinutes??0)>=480)return false;const date=new Date(item.scheduledAt);const minutes=date.getHours()*60+date.getMinutes()-startHour*60;return minutes>=0&&minutes<slotCount*30}).map((item)=>{const date=new Date(item.scheduledAt);const minutes=date.getHours()*60+date.getMinutes()-startHour*60;const top=minutes/30*GRID_SLOT_HEIGHT;const height=Math.max(24,Math.min((item.task.durationMinutes??30)/30*GRID_SLOT_HEIGHT,totalHeight-top));return <button key={`${item.task.id}-${item.occurrenceDay}`} {...dragTask(item.task,item.occurrenceDay)} onClick={(event)=>{event.stopPropagation();onEdit(item.task)}} className="time-event" style={{top,height}}><span>{formatScheduledTime(item.scheduledAt,timeFormat)}</span><strong>{item.task.title}</strong><small>{studentName(item.task.studentId,students)}</small></button>})}</div>)}</div></div></section>;
}

function RepeatDays({days,onChange}:{days:number[];onChange:(days:number[])=>void}){const labels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return <div className="repeat-days" aria-label="Repeat days">{[1,2,3,4,5,6,0].map((day)=>{const selected=days.includes(day);return <button type="button" key={day} aria-pressed={selected} onClick={()=>{const next=selected?days.filter((item)=>item!==day):[...days,day];if(next.length)onChange(next.sort())}} className={selected?'active':''}>{labels[day]}</button>})}</div>}

function QuickAddDialog({scheduledAt,students,canPickOwner,defaultStudentId,onClose,onCreate}:{scheduledAt:string;students:Student[];canPickOwner:boolean;defaultStudentId:string|null;onClose:()=>void;onCreate:(input:{title:string;studentId:string|null;scheduledAt:string;durationMinutes:number|null;priority:Priority;recurringRule?:string|null})=>void}){
  const [title,setTitle]=useState('');const [studentId,setStudentId]=useState<string|null>(defaultStudentId);const [duration,setDuration]=useState<number>(30);const [priority,setPriority]=useState<Priority>('normal');const [date,setDate]=useState(scheduledAt.slice(0,10));const [time,setTime]=useState(scheduledAt.slice(11,16));const [repeats,setRepeats]=useState(false);const [repeatDays,setRepeatDays]=useState([new Date(scheduledAt).getDay()]);
  const submit=()=>{if(!title.trim()||!date)return;onCreate({title:title.trim(),studentId,scheduledAt:`${date}T${time||'09:00'}:00`,durationMinutes:duration,priority,recurringRule:repeats?serializeWeeklyRule(repeatDays):null})};
  return <div className="dialog-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose()}}><section className="dialog quick-add-dialog"><header><div><h2>Quick add</h2><p className="muted-copy">Adjust anything before adding.</p></div><button className="icon-button" aria-label="Close quick add" onClick={onClose}><X/></button></header><label>Task<input autoFocus value={title} onChange={(e)=>setTitle(e.target.value)} onKeyDown={(e)=>{if(e.key==='Enter')submit()}} placeholder="Task or appointment"/></label><fieldset className="quick-schedule"><legend>Schedule</legend><div className="two-col"><input aria-label="Date" type="date" value={date} onChange={(e)=>setDate(e.target.value)}/><input aria-label="Time" type="time" step="1800" value={time} onChange={(e)=>setTime(e.target.value)}/></div></fieldset><div className={`quick-fields${canPickOwner?' with-owner':''}`}>{canPickOwner&&<label>Owner<select value={studentId??''} onChange={(e)=>setStudentId(e.target.value||null)}><option value="">Advisor</option>{students.map((s)=><option key={s.id} value={s.id}>{s.displayName}</option>)}</select></label>}<label>Duration<select value={duration} onChange={(e)=>setDuration(Number(e.target.value))}>{[15,30,45,60,90,120,180,240,480].map((n)=><option key={n} value={n}>{n>=480?'All day':`${n} minutes`}</option>)}</select></label><label>Priority<select value={priority} onChange={(e)=>setPriority(e.target.value as Priority)}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select></label><label>Repeat<select value={repeats?'weekly':'once'} onChange={(e)=>setRepeats(e.target.value==='weekly')}><option value="once">Once</option><option value="weekly">Weekly on selected days</option></select></label></div>{repeats&&<fieldset><legend>Repeat on</legend><RepeatDays days={repeatDays} onChange={setRepeatDays}/><p className="muted-copy">Local rule: {serializeWeeklyRule(repeatDays)}</p></fieldset>}<div className="warning-line"><AlertTriangle size={16}/>Quick add and recurrence schedule work only. They never set or confirm a due date.</div><footer><span/><span/><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" onClick={submit} disabled={!title.trim()||!date}><Plus size={16}/>Add to tasks + calendar</button></footer></section></div>;
}

function StudentsView({students,tasks,onOpen,onAdd,onEdit}:{students:Student[];tasks:Task[];onOpen:(id:string)=>void;onAdd:()=>void;onEdit:(s:Student)=>void}){
  const today=isoToday();
  const [page,setPage]=useState(0);
  const pageSize=8;
  const rows=students.map((student)=>{const open=tasks.filter((task)=>task.studentId===student.id&&!task.deletedAt&&task.workStatus!=='done');const overdue=open.filter(isConfirmedOverdue).length;const dueToday=open.filter((task)=>task.dateConfidence==='confirmed'&&task.dueDate===today).length;return{student,open,overdue,dueToday}}).sort((a,b)=>b.overdue-a.overdue||b.dueToday-a.dueToday||b.open.length-a.open.length||a.student.displayName.localeCompare(b.student.displayName));
  const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));
  useEffect(()=>setPage((current)=>Math.min(current,pageCount-1)),[pageCount]);
  const shown=rows.slice(page*pageSize,(page+1)*pageSize);
  return <div className="students-page"><section className="page-title students-title"><div><h1>Students</h1><p>Each student has a separate task list and calendar.</p></div><div className="students-title-actions student-page-tools">{pageCount>1&&<div className="page-pager"><button onClick={()=>setPage((current)=>Math.max(0,current-1))} disabled={page===0} aria-label="Previous students"><ChevronLeft size={15}/></button><span>{page+1} / {pageCount}</span><button onClick={()=>setPage((current)=>Math.min(pageCount-1,current+1))} disabled={page>=pageCount-1} aria-label="Next students"><ChevronRight size={15}/></button></div>}<button className="secondary add-student-button" onClick={onAdd} aria-label="Add student" title="Add student"><Plus size={17}/><span>Add student</span></button></div></section><section className="student-grid">{shown.length?shown.map(({student,open,overdue,dueToday})=>{const summary=!open.length?'Clear':[`${open.length} open`,dueToday?`${dueToday} due today`:'',overdue?`${overdue} overdue`:''].filter(Boolean).join(' · ');return <div className="student-card" key={student.id}><button className="student-open" onClick={()=>onOpen(student.id)}><span className="avatar">{student.initials}</span><span className="student-copy"><strong>{student.displayName}</strong><small>{summary}</small></span><ChevronRight size={18} className="student-chevron"/></button><button className="student-manage-button" onClick={()=>onEdit(student)} title={`Manage ${student.displayName}`} aria-label={`Manage ${student.displayName}`}><MoreHorizontal size={18}/></button></div>}):<div className="empty student-empty"><p>No students yet.</p><button className="secondary" onClick={onAdd}><Plus size={16}/>Add student</button></div>}</section></div>;
}


function SettingsView({snapshot,patchSettings,runtime,notice,setNotice,onExport,onRestore,onReadiness,readiness,onSync,onImport,onCanvasSync,canvasToken,setCanvasToken,canvasConnection,setCanvasConnection,agent,setAgent,replaceSnapshot,studentPairInput,setStudentPairInput,onPairStudent}:{snapshot:AppSnapshot;patchSettings:(p:Partial<AppSettings>)=>void;runtime:any;notice:string;setNotice:(s:string)=>void;onExport:()=>void;onRestore:()=>void;onReadiness:()=>void;readiness:ReadinessReport|null;onSync:()=>void;onImport:()=>void;onCanvasSync:()=>void;canvasToken:string;setCanvasToken:(s:string)=>void;canvasConnection:any;setCanvasConnection:(v:any)=>void;agent:any;setAgent:(v:any)=>void;replaceSnapshot:(s:AppSnapshot)=>void;studentPairInput:string;setStudentPairInput:(s:string)=>void;onPairStudent:()=>void}){
  async function copilotTest(){try{if(!snapshot.settings.copilotUrl.trim())throw new Error('Add the approved Copilot URL first.');await openCopilotWindow(snapshot.settings.copilotUrl);await new Promise((r)=>window.setTimeout(r,2500));const result=await probeCopilotWindow();const responses=Array.isArray(result.responseContainers)?result.responseContainers.length:0;setNotice(`Copilot probe: ${Array.isArray(result.editables)?result.editables.length:0} input candidate(s), ${Array.isArray(result.buttons)?result.buttons.length:0} send/button candidate(s), ${responses} response container(s). No auth tokens, cookies, localStorage, or passwords were read.`);}catch(e){setNotice(e instanceof Error?e.message:'Copilot test failed.')}}
  async function outlookAction(){try{if(snapshot.outlook.accountLabel){setNotice('Disconnecting Outlook…');const next=await disconnectOutlook(snapshot);replaceSnapshot({...next,settings:{...next.settings,outlookEnabled:false}});setNotice('Outlook disconnected.');return;}const next=await connectOutlook(snapshot);replaceSnapshot({...next,settings:{...next.settings,outlookEnabled:true}});setNotice(`Outlook connected as ${next.outlook.accountLabel}.`);}catch(e){setNotice(e instanceof Error?e.message:'Outlook connection failed.')}}
  async function canvasAction(){try{if(canvasConnection.connected){await disconnectCanvas();setCanvasConnection({connected:false,accountLabel:null,baseUrl:null});setNotice('Canvas disconnected.');return;}const r=await connectCanvas(snapshot.settings.canvasBaseUrl,canvasToken);setCanvasToken('');setCanvasConnection({connected:true,accountLabel:r.accountLabel,baseUrl:snapshot.settings.canvasBaseUrl});setNotice(`Canvas connected as ${r.accountLabel}. Token stored with Windows DPAPI.`);}catch(e){setNotice(e instanceof Error?e.message:'Canvas connection failed.')}}
  return <div className="settings-page"><section className="page-title stacked"><div><h1>Settings</h1><p>Core tasks remain available when integrations are offline.</p></div></section><section className="settings-stack">
    <div className="settings-grid">
      <IntegrationCard title="Canvas" description={canvasConnection.connected?`Connected: ${canvasConnection.accountLabel}`:'Not connected'} action={canvasConnection.connected?'Disconnect':'Connect'} onAction={canvasAction}/>
      <IntegrationCard title="Microsoft Outlook" description={snapshot.outlook.accountLabel?`Connected: ${snapshot.outlook.accountLabel} \u00b7 ${snapshot.outlook.message??'ready'}`:'Not connected'} action={snapshot.outlook.accountLabel?'Disconnect':'Connect'} onAction={outlookAction}/>
      <IntegrationCard title="Copilot bridge" description={snapshot.settings.copilotEnabled?'Enabled \u00b7 Microsoft session stays in a separate local WebView':'Disabled \u00b7 local organizer available'} action="Test" onAction={copilotTest}/>
      <button className="settings-action backup-export-card" onClick={onExport}><Download size={16}/>Export JSON backup</button>
      <div className="integration-card shortcut-card"><div><strong>Keyboard shortcut</strong><small>Ctrl/{'\u2318'} N focuses the info dump.</small></div></div>
    </div>
    <details className="advanced-settings settings-advanced"><summary>Advanced desktop settings</summary><div className="advanced-nested"><details className="advanced-settings desktop-tools"><summary>Desktop tools</summary><div className="desktop-tools-grid"><IntegrationCard title="Academic import" description={`${snapshot.settings.academicImportMode} \u00b7 local file import never uploads the file`} action="Import file" onAction={onImport}/><IntegrationCard title="Student sync" description={snapshot.settings.syncTransportMode==='disabled'?'Not configured':snapshot.sync.state==='error'?(snapshot.sync.message??'Needs attention'):snapshot.syncQueue.length?`${snapshot.syncQueue.length} change${snapshot.syncQueue.length===1?'':'s'} waiting to sync`:'Up to date'} action="Sync now" onAction={onSync}/><div className="integration-card"><div><strong>Restore backup</strong><small>Replace local data from a Torgy JSON backup.</small></div><button className="secondary" onClick={onRestore}><RefreshCw size={16}/>Restore</button></div><div className="integration-card calendar-preferences-card"><div><strong>Calendar</strong><small>Choose the visible day range and clock format.</small><div className="calendar-preference-controls"><label>Day range<select aria-label="Calendar day range" value={snapshot.settings.calendarDayRange} onChange={(e)=>patchSettings({calendarDayRange:e.target.value as AppSettings['calendarDayRange']})}><option value="standard">Standard \u00b7 8 AM–7 PM</option><option value="full-day">Full 24 hours</option><option value="custom">Custom hours</option></select></label><label>Clock<select aria-label="Calendar time format" value={snapshot.settings.calendarTimeFormat} onChange={(e)=>patchSettings({calendarTimeFormat:e.target.value as AppSettings['calendarTimeFormat']})}><option value="12h">12-hour</option><option value="24h">24-hour</option></select></label>{snapshot.settings.calendarDayRange==='custom'&&<><label>Start<select aria-label="Calendar start hour" value={snapshot.settings.calendarDayStartHour} onChange={(e)=>{const start=Number(e.target.value);patchSettings({calendarDayStartHour:start,calendarDayEndHour:Math.max(start+1,snapshot.settings.calendarDayEndHour)})}}>{Array.from({length:24},(_,hour)=><option value={hour} key={hour}>{calendarHourLabel(hour,snapshot.settings.calendarTimeFormat)}</option>)}</select></label><label>End<select aria-label="Calendar end hour" value={snapshot.settings.calendarDayEndHour} onChange={(e)=>patchSettings({calendarDayEndHour:Number(e.target.value)})}>{Array.from({length:24-snapshot.settings.calendarDayStartHour},(_,index)=>snapshot.settings.calendarDayStartHour+index+1).map((hour)=><option value={hour} key={hour}>{calendarHourLabel(hour,snapshot.settings.calendarTimeFormat)}</option>)}</select></label></>}</div></div></div>{snapshot.settings.role==='student'&&<div className="integration-card pairing-panel"><div><strong>Pair with advisor</strong><small>The code is created from the staff-only drive. Your user account never receives drive access.</small><input value={studentPairInput} onChange={(e)=>setStudentPairInput(e.target.value.toUpperCase())} placeholder="PAIRING CODE"/></div><button className="secondary" onClick={onPairStudent}>Pair</button></div>}</div><div className="security-box local-runtime-box"><ShieldCheck size={20}/><div><strong>Local runtime</strong><small>{runtime.platform} {'\u00b7'} {runtime.storage}</small>{runtime.appDataDir&&<small className="mono">{runtime.appDataDir}</small>}</div></div></details>
    <details className="advanced-settings readiness-fold"><summary>Installation readiness</summary><div className="readiness-body"><div className="readiness-head"><small>Checks the local runtime and each configured connector without exposing secrets.</small><button className="secondary" onClick={onReadiness}><ShieldCheck size={16}/>Run check</button></div>{readiness&&<div className="readiness-list">{readiness.checks.map((item)=><div className={`readiness-row ${item.status}`} key={item.key}><span className="readiness-dot"/><div><strong>{item.label}</strong><small>{item.detail}</small></div></div>)}</div>}</div></details>
    <details className="advanced-settings"><summary>Integration configuration</summary>
      <label>Installation role<select value={snapshot.settings.role} onChange={(e)=>patchSettings({role:e.target.value as AppSettings['role'],selectedStudentId:e.target.value==='student'?(snapshot.students[0]?.id??'all'):snapshot.settings.selectedStudentId})}><option value="coordinator">Advisor</option><option value="student">Student</option></select></label>
      <label>Approved Copilot URL<input value={snapshot.settings.copilotUrl} onChange={(e)=>patchSettings({copilotUrl:e.target.value})}/></label><label className="switch-row"><span>Enable Copilot</span><input type="checkbox" checked={snapshot.settings.copilotEnabled} onChange={(e)=>patchSettings({copilotEnabled:e.target.checked})}/></label>
      <label>Outlook tenant ID<input value={snapshot.settings.outlookTenantId} onChange={(e)=>patchSettings({outlookTenantId:e.target.value})}/></label><label>Outlook public client ID<input value={snapshot.settings.outlookClientId} onChange={(e)=>patchSettings({outlookClientId:e.target.value})}/></label><label className="switch-row"><span>Enable automatic Outlook sync</span><input type="checkbox" checked={snapshot.settings.outlookEnabled} onChange={(e)=>patchSettings({outlookEnabled:e.target.checked})}/></label>
      <label>Sync transport<select value={snapshot.settings.syncTransportMode} onChange={(e)=>patchSettings({syncTransportMode:e.target.value as AppSettings['syncTransportMode'],syncEnabled:e.target.value!=='disabled'})}><option value="disabled">Disabled</option>{snapshot.settings.role==='coordinator'?<option value="staff-drive">Staff/faculty direct drive access</option>:<option value="managed-agent">Student managed SYSTEM agent</option>}</select></label>{snapshot.settings.role==='coordinator'?<label>University sync drive path<input value={snapshot.settings.syncSharePath} onChange={(e)=>patchSettings({syncSharePath:e.target.value})} placeholder="\\server\staff\TorgySync"/></label>:<div className="security-box"><ShieldCheck size={18}/><div><strong>Managed student transport</strong><small>The staff/faculty drive path and credentials are never stored in the student Torgy profile. The SYSTEM worker receives its transport configuration from the university deployment package.</small><small>{agent.configured?agent.message:'IT deployment configuration is still required on this device.'}</small></div></div>}
      <label>Academic source<select value={snapshot.settings.academicImportMode} onChange={(e)=>patchSettings({academicImportMode:e.target.value as AppSettings['academicImportMode']})}><option value="manual">Local export</option><option value="docs">Google Docs/Sheets export</option><option value="canvas">Direct Canvas</option></select></label>{snapshot.settings.academicImportMode==='canvas'&&<><label>Canvas URL<input value={snapshot.settings.canvasBaseUrl} onChange={(e)=>patchSettings({canvasBaseUrl:e.target.value})}/></label>{!canvasConnection.connected&&<label>Canvas token<input type="password" value={canvasToken} onChange={(e)=>setCanvasToken(e.target.value)} autoComplete="off"/></label>}{canvasConnection.connected&&<button className="secondary" onClick={onCanvasSync}>Sync Canvas now</button>}</>}
    </details></div></details>
    {notice&&<p className="notice settings-notice">{notice}</p>}
  </section></div>;
}

function IntegrationCard({title,description,action,onAction}:{title:string;description:string;action:string;onAction:()=>void}){return <div className="integration-card"><div><strong>{title}</strong><small>{description}</small></div><button className="secondary" onClick={onAction}><RefreshCw size={16}/>{action}</button></div>}
function BottomNav({view,setView,role}:{view:AppView;setView:(v:AppView)=>void;role:AppSettings['role']}){const items:{view:AppView;icon:ReactNode;label:string;visible:boolean}[]=[{view:'tasks',icon:<ClipboardList size={20}/>,label:'Tasks',visible:true},{view:'calendar',icon:<CalendarDays size={20}/>,label:'Calendar',visible:true},{view:'students',icon:<Users size={20}/>,label:'Students',visible:role==='coordinator'},{view:'settings',icon:<Settings size={20}/>,label:'Settings',visible:true}];return <nav className="bottom-nav">{items.filter((i)=>i.visible).map((i)=><button key={i.view} className={view===i.view?'active':''} onClick={()=>setView(i.view)} title={i.label}>{i.icon}</button>)}</nav>}
function SearchDialog({snapshot,query,setQuery,onClose,onOpenTask,onOpenStudent}:{snapshot:AppSnapshot;query:string;setQuery:(value:string)=>void;onClose:()=>void;onOpenTask:(task:Task)=>void;onOpenStudent:(id:string)=>void}){const needle=query.trim().toLowerCase();const taskResults=needle?snapshot.tasks.filter((task)=>!task.deletedAt&&[task.title,task.course??'',task.source,studentName(task.studentId,snapshot.students),dateLabel(task)].join(' ').toLowerCase().includes(needle)).slice(0,12):[];const studentResults=needle?snapshot.students.filter((student)=>student.displayName.toLowerCase().includes(needle)).slice(0,8):[];return <div className="dialog-backdrop search-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)onClose()}}><section className="search-dialog" role="dialog" aria-label="Search Torgy"><div className="search-input-wrap"><Search size={18}/><input autoFocus value={query} onChange={(event)=>setQuery(event.target.value)} onKeyDown={(event)=>{if(event.key==='Escape')onClose()}} placeholder="Search students, tasks, courses, sources, or dates"/><kbd>Esc</kbd></div>{!needle?<div className="search-empty"><strong>Search everything in Torgy</strong><span>Try a student name, course, task, Canvas, or a date.</span></div>:<div className="search-results">{studentResults.length>0&&<section><h3>Students</h3>{studentResults.map((student)=><button key={student.id} onClick={()=>onOpenStudent(student.id)}><span className="avatar mini">{student.initials}</span><span><strong>{student.displayName}</strong><small>Open student workspace</small></span><ChevronRight size={16}/></button>)}</section>}{taskResults.length>0&&<section><h3>Tasks</h3>{taskResults.map((task)=><button key={task.id} onClick={()=>onOpenTask(task)}><span><strong>{task.title}</strong><small>{studentName(task.studentId,snapshot.students)}{task.course?` · ${task.course}`:''} · {dateLabel(task)}</small></span><ChevronRight size={16}/></button>)}</section>}{studentResults.length===0&&taskResults.length===0&&<div className="search-empty"><strong>No results</strong><span>Try another word or name.</span></div>}</div>}</section></div>}
function StudentDialog({student,onClose,onSave,onDelete,onPair}:{student:Student|null;onClose:()=>void;onSave:(s:Pick<Student,'id'|'displayName'|'initials'|'mailboxId'|'canvasUserId'>)=>void;onDelete?:()=>void;onPair?:()=>void}){const[name,setName]=useState(student?.displayName??'');const[initials,setInitials]=useState(student?.initials??'');const[canvasUserId,setCanvasUserId]=useState(student?.canvasUserId??'');return <div className="dialog-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose()}}><section className="dialog student-dialog"><header><h2>{student?'Student details':'Add student'}</h2><button className="icon-button" aria-label="Close student details" onClick={onClose}><X/></button></header>{student&&<div className="student-dialog-status"><div><strong>Pairing and student sync</strong><small>{student.pairingState} · {student.syncState}</small></div>{onPair&&<button className="secondary compact" onClick={onPair}><Link2 size={14}/>{student.pairingState==='paired'?'Re-pair':'Pair'}</button>}</div>}<label>Name<input autoFocus value={name} onChange={(e)=>setName(e.target.value)}/></label><label>Initials<input value={initials} onChange={(e)=>setInitials(e.target.value.slice(0,4).toUpperCase())}/></label><label>Canvas user ID (optional)<input value={canvasUserId} onChange={(e)=>setCanvasUserId(e.target.value)}/></label><p className="muted-copy">The sync mailbox uses a random ID; the student's name is not a folder name.</p><footer>{onDelete?<button className="danger-link" onClick={onDelete}>Remove student</button>:<span/>}<span/><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" onClick={()=>onSave({id:student?.id??crypto.randomUUID(),displayName:name,initials,mailboxId:student?.mailboxId??crypto.randomUUID(),canvasUserId})} disabled={!name.trim()}><Save size={16}/>Save</button></footer></section></div>}
function TaskDialog({task,students,roleLabel,onClose,onSave,onDelete}:{task:Task;students:Student[];roleLabel:string;onClose:()=>void;onSave:(task:Task)=>void;onDelete:()=>void}){
  const [draft,setDraft]=useState(task);const scheduleDate=draft.scheduledAt?.slice(0,10)??'';const scheduleTime=draft.scheduledAt?.slice(11,16)??'';const weekly=parseWeeklyRule(draft.recurringRule,draft.scheduledAt);const patch=(value:Partial<Task>)=>setDraft((current)=>({...current,...value}));
  function setConfidence(value:DateConfidence){if(value==='confirmed')patch({dateConfidence:'confirmed',dueDate:draft.dueDate??draft.possibleDate??isoToday(),possibleDate:null});else if(value==='possible')patch({dateConfidence:'possible',possibleDate:draft.possibleDate??draft.dueDate??isoToday(),dueDate:null});else patch({dateConfidence:'undated',dueDate:null,possibleDate:null})}
  function setSchedule(date:string,time:string){patch({scheduledAt:date?`${date}T${time||'09:00'}:00`:null,recurringRule:date?draft.recurringRule:null})}
  return <div className="dialog-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)onClose()}}><section className="dialog"><header><div><h2>Task details</h2><p className="muted-copy">Due date and work schedule stay separate.</p></div><button className="icon-button" onClick={onClose}><X/></button></header><label>Title<input value={draft.title} onChange={(event)=>patch({title:event.target.value})}/></label><div className="two-col"><label>Duration<select value={draft.durationMinutes??''} onChange={(event)=>patch({durationMinutes:event.target.value?Number(event.target.value):null})}><option value="">None</option>{[15,30,45,60,90,120,180,240,480].map((minutes)=><option value={minutes} key={minutes}>{minutes>=480?'All day':`${minutes} minutes`}</option>)}</select></label><label>Priority<select value={draft.priority} onChange={(event)=>patch({priority:event.target.value as Priority})}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select></label></div><label>Owner<select value={draft.studentId??''} onChange={(event)=>patch({studentId:event.target.value||null})}><option value="">{roleLabel==='Advisor view'?'Advisor':'Personal'}</option>{students.map((student)=><option value={student.id} key={student.id}>{student.displayName}</option>)}</select></label><div className="two-col"><label>Date status<select value={draft.dateConfidence} onChange={(event)=>setConfidence(event.target.value as DateConfidence)}><option value="confirmed">Confirmed</option><option value="possible">Possible</option><option value="undated">No date</option></select></label><label>{draft.dateConfidence==='possible'?'Possible date':'Due date'}<input type="date" disabled={draft.dateConfidence==='undated'} value={draft.dueDate??draft.possibleDate??''} onChange={(event)=>draft.dateConfidence==='confirmed'?patch({dueDate:event.target.value||null}):patch({possibleDate:event.target.value||null})}/></label></div>{draft.dateConfidence==='possible'&&<div className="warning-line"><AlertTriangle size={16}/>Not authoritative until a human changes it to Confirmed.</div>}<fieldset><legend>Schedule (syncs to Outlook; does not change due date)</legend><div className="two-col"><input aria-label="Schedule date" type="date" value={scheduleDate} onChange={(event)=>setSchedule(event.target.value,scheduleTime)}/><input aria-label="Schedule time" type="time" step="1800" disabled={!scheduleDate} value={scheduleTime} onChange={(event)=>setSchedule(scheduleDate,event.target.value)}/></div></fieldset><label>Repeat<select disabled={!draft.scheduledAt} value={weekly?'weekly':'once'} onChange={(event)=>patch({recurringRule:event.target.value==='weekly'?serializeWeeklyRule([new Date(draft.scheduledAt!).getDay()]):null})}><option value="once">Once</option><option value="weekly">Weekly on selected days</option></select></label>{weekly&&<fieldset><legend>Repeat on</legend><RepeatDays days={weekly.days} onChange={(days)=>patch({recurringRule:setWeeklyDays(draft.recurringRule,days)})}/><p className="muted-copy">Rule: {draft.recurringRule}. Moving one calendar occurrence creates a local exception without changing this series or its due date.</p></fieldset>}{!draft.scheduledAt&&<p className="muted-copy">Add a schedule before enabling repeat.</p>}<label>Notes<textarea className="notes-input" value={draft.notes} onChange={(event)=>patch({notes:event.target.value})}/></label><footer><button className="danger-link" onClick={onDelete}>Delete</button><span/><button className="secondary" onClick={onClose}>Cancel</button><button className="primary" onClick={()=>onSave(draft)} disabled={!draft.title.trim()}><Save size={16}/>Save</button></footer></section></div>
}
function SimpleDialog({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}){return <div className="dialog-backdrop" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose()}}><section className="dialog"><header><h2>{title}</h2><button className="icon-button" onClick={onClose}><X/></button></header>{children}<footer><span/><span/><button className="primary" onClick={onClose}>Done</button></footer></section></div>}
